import React, { useState, useEffect } from "react"
import styled from "@emotion/styled"
import { colors, MediaQueries } from "../GlobalCSSVariables"

const PARADE_DATE = new Date("2026-06-13T09:00:00")

function getTimeLeft() {
  const now = new Date()
  const diff = PARADE_DATE - now
  if (diff <= 0) return { days: 0, hours: 0, minutes: 0, seconds: 0 }
  return {
    days: Math.floor(diff / (1000 * 60 * 60 * 24)),
    hours: Math.floor((diff / (1000 * 60 * 60)) % 24),
    minutes: Math.floor((diff / (1000 * 60)) % 60),
    seconds: Math.floor((diff / 1000) % 60),
  }
}

const Wrap = styled.section`
  background-color: ${colors.surface};
  border-bottom: 1px solid rgba(245, 240, 232, 0.07);
  padding: 64px 24px;
  position: relative;
  overflow: hidden;

  &::before {
    content: "";
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 3px;
    background: linear-gradient(90deg, ${colors.red}, ${colors.gold}, ${colors.green});
  }

  ${MediaQueries.md} {
    padding: 80px 64px;
  }
`

const Inner = styled.div`
  max-width: 880px;
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
`

const Eyebrow = styled.p`
  font-family: "Inter", sans-serif;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.26em;
  text-transform: uppercase;
  color: ${colors.red};
  margin: 0 0 12px;
`

const SubTitle = styled.p`
  font-family: "Playfair Display", "Georgia", serif;
  font-size: clamp(1rem, 2.2vw, 1.35rem);
  font-weight: 700;
  color: ${colors.cream};
  margin: 0 0 44px;
  opacity: 0.85;
`

const ClockRow = styled.div`
  display: flex;
  align-items: flex-start;
  gap: 12px;

  ${MediaQueries.sm} {
    gap: 24px;
  }
`

const ClockUnit = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 10px;
  min-width: 68px;

  ${MediaQueries.sm} {
    min-width: 88px;
  }
`

const NumBox = styled.div`
  background-color: ${colors.surface2};
  border: 1px solid rgba(245, 240, 232, 0.08);
  padding: 16px 12px 14px;
  width: 100%;
  position: relative;
  overflow: hidden;

  &::after {
    content: "";
    position: absolute;
    bottom: 0; left: 0; right: 0;
    height: 2px;
    background: ${colors.red};
  }

  ${MediaQueries.sm} {
    padding: 20px 16px 18px;
  }
`

const Num = styled.span`
  font-family: "Playfair Display", "Georgia", serif;
  font-size: clamp(2.2rem, 5.5vw, 4rem);
  font-weight: 900;
  color: ${colors.white};
  line-height: 1;
  letter-spacing: -0.04em;
  display: block;
  text-align: center;
`

const UnitLabel = styled.span`
  font-family: "Inter", sans-serif;
  font-size: 0.58rem;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: ${colors.creamMuted};
`

const Colon = styled.span`
  font-family: "Playfair Display", "Georgia", serif;
  font-size: clamp(1.8rem, 4vw, 3rem);
  font-weight: 900;
  color: ${colors.gold};
  line-height: 1;
  padding-top: 14px;
  flex-shrink: 0;

  ${MediaQueries.sm} {
    padding-top: 18px;
  }
`

const CountdownTimer = () => {
  const [time, setTime] = useState({ days: 0, hours: 0, minutes: 0, seconds: 0 })
  const [mounted, setMounted] = useState(false)

  useEffect(() => {
    setMounted(true)
    setTime(getTimeLeft())
    const id = setInterval(() => setTime(getTimeLeft()), 1000)
    return () => clearInterval(id)
  }, [])

  const pad = n => String(n).padStart(2, "0")

  if (!mounted) return null

  return (
    <Wrap>
      <Inner>
        <Eyebrow>Countdown to the Parade</Eyebrow>
        <SubTitle>Saturday, June 13, 2026 · 9:00 AM · Kansas City, KS</SubTitle>
        <ClockRow>
          <ClockUnit>
            <NumBox><Num>{time.days}</Num></NumBox>
            <UnitLabel>Days</UnitLabel>
          </ClockUnit>
          <Colon>:</Colon>
          <ClockUnit>
            <NumBox><Num>{pad(time.hours)}</Num></NumBox>
            <UnitLabel>Hours</UnitLabel>
          </ClockUnit>
          <Colon>:</Colon>
          <ClockUnit>
            <NumBox><Num>{pad(time.minutes)}</Num></NumBox>
            <UnitLabel>Mins</UnitLabel>
          </ClockUnit>
          <Colon>:</Colon>
          <ClockUnit>
            <NumBox><Num>{pad(time.seconds)}</Num></NumBox>
            <UnitLabel>Secs</UnitLabel>
          </ClockUnit>
        </ClockRow>
      </Inner>
    </Wrap>
  )
}

export default CountdownTimer