import React, { useState, useEffect } from "react"
import styled from "@emotion/styled"
import { colors, MediaQueries } from "../GlobalCSSVariables"

const Bar = styled.div`
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 1200;
  background-color: ${colors.red};
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 14px 20px;
  transform: translateY(${({ visible }) => (visible ? "0" : "100%")});
  transition: transform 0.35s cubic-bezier(0.4, 0, 0.2, 1);
  box-shadow: 0 -4px 24px rgba(200, 16, 46, 0.35);

  /* Only show on mobile */
  ${MediaQueries.md} {
    display: none;
  }
`

const BarText = styled.p`
  font-family: "Inter", sans-serif;
  font-size: 0.76rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: ${colors.white};
  margin: 0;
  line-height: 1.3;
  flex: 1;
`

const Deadline = styled.span`
  display: block;
  font-size: 0.62rem;
  font-weight: 400;
  letter-spacing: 0.14em;
  color: rgba(255,255,255,0.7);
  margin-top: 2px;
`

const BarBtn = styled.a`
  font-family: "Inter", sans-serif;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: ${colors.black};
  background-color: ${colors.gold};
  padding: 10px 18px;
  white-space: nowrap;
  flex-shrink: 0;
  transition: background-color 0.2s ease;
  &:hover { background-color: ${colors.goldMuted}; }
`

const DismissBtn = styled.button`
  background: none;
  border: none;
  color: rgba(255,255,255,0.5);
  font-size: 1.1rem;
  cursor: pointer;
  padding: 4px 6px;
  line-height: 1;
  flex-shrink: 0;
  transition: color 0.2s ease;
  &:hover { color: ${colors.white}; }
`

const StickyBar = () => {
  const [visible, setVisible] = useState(false)
  const [dismissed, setDismissed] = useState(false)

  useEffect(() => {
    if (dismissed) return
    const onScroll = () => {
      setVisible(window.scrollY > 320)
    }
    window.addEventListener("scroll", onScroll, { passive: true })
    return () => window.removeEventListener("scroll", onScroll)
  }, [dismissed])

  const handleDismiss = e => {
    e.preventDefault()
    setDismissed(true)
    setVisible(false)
  }

  if (dismissed) return null

  return (
    <Bar visible={visible ? 1 : 0}>
      <BarText>
        Join the 2026 Parade
        <Deadline>Deadline: May 31, 2026</Deadline>
      </BarText>
      <BarBtn href="./2026Waiver.pdf" target="_blank" rel="noreferrer">
        Register
      </BarBtn>
      <DismissBtn onClick={handleDismiss} aria-label="Dismiss">✕</DismissBtn>
    </Bar>
  )
}

export default StickyBar